CREATE OR REPLACE PROCEDURE sp(arg1 integer, arg2 text, arg3 integer, arg4 integer, arg5 text, arg6 integer)
LANGUAGE plpgsql AS
$$
DECLARE
    v_remembered_railway_id integer;
    v_assignment_count integer;
    v_railway_assignment_count integer;
    v_train_count integer;
BEGIN
    SELECT MIN("Railway_ID") INTO v_remembered_railway_id
    FROM "railway_manage"
    WHERE "From_Year" = arg5;

    IF v_remembered_railway_id IS NOT NULL AND arg3 > 3 THEN
        CALL sp_part1(arg1, arg2, arg3, arg4, arg5, arg6);
        CALL sp_part2(arg5, v_remembered_railway_id);

        UPDATE "railway" SET "Built" = arg3 WHERE "Railway_ID" = arg6;
    ELSE
        CALL sp_part2(arg5, arg6 + 1);

        IF arg3 <= 3 THEN
            DELETE FROM "railway_manage"
            WHERE "Manager_ID" = arg4 AND "Railway_ID" < arg6;
        ELSE
            DELETE FROM "railway_manage"
            WHERE "Railway_ID" = arg6 AND "From_Year" = arg5;
        END IF;
    END IF;

    IF arg2 IS NOT NULL THEN
        UPDATE "manager"
        SET "Country" = 'archive_' || "Country"
        WHERE "Manager_ID" = arg4
          AND "Working_year_starts" = arg2
          AND "Country" IS NOT NULL
          AND "Country" NOT LIKE 'archive\_%' ESCAPE '\';
    END IF;

    SELECT COUNT(*) INTO v_assignment_count
    FROM "railway_manage"
    WHERE "Manager_ID" = arg4;

    IF v_assignment_count = 0 THEN
        UPDATE "manager"
        SET "Name" = 'inactive_' || "Name"
        WHERE "Manager_ID" = arg4
          AND "Name" IS NOT NULL
          AND "Name" NOT LIKE 'inactive\_%' ESCAPE '\';
    END IF;

    SELECT COUNT(*) INTO v_railway_assignment_count
    FROM "railway_manage"
    WHERE "Railway_ID" = arg6;

    IF v_railway_assignment_count = 0 THEN
        UPDATE "railway"
        SET "Location" = 'unassigned_' || "Location"
        WHERE "Railway_ID" = arg6
          AND "Location" IS NOT NULL
          AND "Location" NOT LIKE 'unassigned\_%' ESCAPE '\';
    END IF;

    SELECT COUNT(*) INTO v_train_count
    FROM "train"
    WHERE "Railway_ID" = arg6;

    IF v_train_count = 0 THEN
        UPDATE "railway"
        SET "Builder" = 'no_train_' || "Builder"
        WHERE "Railway_ID" = arg6
          AND "Builder" IS NOT NULL
          AND "Builder" NOT LIKE 'no_train\_%' ESCAPE '\';
    END IF;
END;
$$;

